    const carousel=root.querySelector('.wb-carousel');if(carousel){const update=()=>{const card=carousel.querySelector('.wb-interview-card');if($('wb-card-position'))$('wb-card-position').textContent=`${Math.min(carousel.children.length,Math.round(carousel.scrollLeft/(card.getBoundingClientRect().width+12))+1)} / ${carousel.children.length}`;};carousel.addEventListener('scroll',update);const next=selectedDay===day()?InterviewPreparation.next(state.events):null,index=[...carousel.children].findIndex(c=>c.dataset.interviewId===next?.id);if(index>0)requestAnimationFrame(()=>{carousel.scrollLeft=index*(carousel.children[0].getBoundingClientRect().width+12);update();});carousel.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();slide(e.key==='ArrowLeft'?-1:1);}};}
