  let presentationObserver=null;
  const recordedPresentation=new Set();
  function observeOpportunities(){
    presentationObserver?.disconnect();
    presentationObserver=new IntersectionObserver(entries=>{if(document.visibilityState!=='visible'||!$('overlay').hidden||route!=='opportunities')return;const visible=entries.filter(e=>e.isIntersecting&&e.intersectionRatio>=0.15&&!recordedPresentation.has(e.target.dataset.presentId)).map(e=>opp(e.target.dataset.presentId)).filter(Boolean).slice(0,200);for(const o of visible)recordedPresentation.add(o.id);if(visible.length)api('opportunities-presented',{items:visible.slice(0,200).map(o=>({id:o.id,revision:o.revision}))}).then(result=>{for(const o of visible)if(!result.accepted.includes(o.id))recordedPresentation.delete(o.id);}).catch(()=>{for(const o of visible)recordedPresentation.delete(o.id);});},{threshold:0.15});
    root.querySelectorAll('[data-present-id]').forEach(e=>presentationObserver.observe(e));
  }
  new MutationObserver(()=>{if(route==='opportunities'&&$('overlay').hidden)requestAnimationFrame(observeOpportunities);}).observe($('overlay'),{attributes:true,attributeFilter:['hidden']});
  document.addEventListener('visibilitychange',()=>{if(route==='opportunities')observeOpportunities();});
