  function mailAIValue(c){if(!c.adoptable)return '需手动填写';if(['startsAt','deadline','endsAt','offerIssuedAt','offerReplyDeadline','joiningAt'].includes(c.key))return new Intl.DateTimeFormat('zh-CN',{timeZone:zone(),year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(new Date(c.normalized));if(c.key==='type')return labels[c.normalized]||c.normalized;if(c.key==='action')return ({create:'新建事件',reschedule:'更新既有事件',cancel:'取消既有事件'})[c.normalized]||c.normalized;return c.normalized;}
