    $('mail-ai-history').onclick=e=>{const result=e.target.closest('[data-mail-ai-result]'),cancel=e.target.closest('[data-mail-ai-cancel]'),remote=e.target.closest('[data-mail-ai-hosted]');if(result)attempt(()=>mailAIReview(jobs.find(j=>j.id===result.dataset.mailAiResult)));if(cancel)attempt(()=>api('mail-ai-cancel',{id:cancel.dataset.mailAiCancel}));if(remote)attempt(()=>mailAIHostedStatus(c.id,remote.dataset.mailAiHosted));};
