    $('wb-profile-group').onchange=e=>profileEditor(e.target.value);
    $('wb-profile-form').oninput=e=>{const match=/^(\d+):(.+)$/.exec(e.target.name||'');if(match){const records=profileDraft.profile.values[group]||(profileDraft.profile.values[group]=[]);records[Number(match[1])]||={};records[Number(match[1])][match[2]]=e.target.value;}};
